attributes.cssVariables:
:root {
  /* Page. Near-black, not pure black — #0d0d12 carries a faint blue cast so the
     magenta reads as ink on a surface rather than as light in a void. */
  --background: #0d0d12;
  --foreground: #f5f5f7;
  --card: #16161d;
  --card-foreground: #f5f5f7;

  /* Not in the pasted style; a card reading --popover would have got nothing.
     Mirrors --card, which is what a popover is: a card that floats. */
  --popover: #16161d;
  --popover-foreground: #f5f5f7;

  /* Electric magenta. On THIS ground it measures 5.58:1 as text, so the style's
     own intent — "powers links and pull quotes" — is safe here. That is a
     property of the dark page, not of the hue: the same magenta on white is
     3.50:1 and could not carry a word. */
  --primary: #ff2d92;
  --primary-foreground: #0d0d12;
  --accent: #ff2d92;
  --accent-foreground: #0d0d12;

  --secondary: #1a1a22;
  --secondary-foreground: #f5f5f7;
  --muted: #15151b;
  --muted-foreground: #a0a0aa;

  /* Also absent from the pasted style. Chosen away from the magenta so a
     destructive action never reads as the accent — 6.36:1 with dark type. */
  --destructive: #ff5c4d;
  --destructive-foreground: #0d0d12;

  --border: #2a2a33;
  --input: #2a2a33;
  --ring: #ff2d92;

  /* 2px, not 0 — the pasted style says "sharp 2px corners", which is a
     different decision from brutalism's hard 0 and is kept as written. */
  --radius: 2px;

  /* One face for everything. A monospace body is the whole terminal idea; it is
     not a code-only choice here. */
  --font-sans: 'JetBrains Mono', 'Fira Code', Menlo, monospace;
  --font-mono: 'JetBrains Mono', 'Fira Code', Menlo, monospace;
  --font-heading: 'JetBrains Mono', 'Fira Code', Menlo, monospace;
  --font-serif: 'JetBrains Mono', 'Fira Code', Menlo, monospace;

  /* On a near-black page a dark shadow is invisible. Depth comes from a
     magenta glow instead — the terminal-phosphor reading of elevation. */
  --shadow-xs: 0 0 0 1px #2a2a33;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.6);
  --shadow-md: 0 4px 18px rgba(0, 0, 0, 0.7);
  --shadow-lg: 0 0 24px rgba(255, 45, 146, 0.18), 0 8px 30px rgba(0, 0, 0, 0.8);
}

h1,
h2,
h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
}
